import { z } from "zod";
import { DIETS } from "#shared/utils/diet";
import type { Diet } from "#shared/utils/diet";

/*
 * GET /api/recipes/:id/swaps/:diet: the protein swap that makes a recipe fit a diet (D2), generated by the AI
 * the first time anyone asks and read from the database after that.
 *
 *   200 { status: "ready", swap }                      stored (or just generated) swap
 *   202 { status: "pending" } + Retry-After            another request is generating it; ask again
 *   503 { status: "unavailable", retryAfter }          generation failed; tried again after that time
 *   404 { status: "not-needed" }                       the recipe already fits the diet
 *   429                                                too many cache misses from this user
 */
const PENDING_RETRY_SECONDS = 3;

const paramsSchema = z.object({
  id: z.guid(),
  diet: z.enum(DIETS),
});

export default defineEventHandler(async (event) => {
  const user = event.context.supabaseUser;
  if (!user) {
    throw createError({ statusCode: 401, statusMessage: "Sign in to see protein swaps" });
  }

  const params = paramsSchema.safeParse(getRouterParams(event));
  if (!params.success) {
    throw createError({ statusCode: 400, statusMessage: "Unknown recipe or diet" });
  }
  const diet: Diet = params.data.diet;

  const result = await useProteinSwapService(event).getOrCreateSwap(params.data.id, diet, {
    allowGenerate: () => allowSwapMiss(user.id),
  });

  switch (result.status) {
    case "ready":
      return { status: "ready", swap: result.swap };
    case "pending":
      setResponseStatus(event, 202);
      setResponseHeader(event, "Retry-After", PENDING_RETRY_SECONDS);
      return { status: "pending" };
    case "unavailable": {
      const seconds = Math.max(1, Math.ceil((result.retryAfter.getTime() - Date.now()) / 1000));
      setResponseStatus(event, 503);
      setResponseHeader(event, "Retry-After", seconds);
      return { status: "unavailable", retryAfter: result.retryAfter.toISOString() };
    }
    case "limited":
      throw createError({ statusCode: 429, statusMessage: "Too many new swap requests; try again later" });
    case "not-needed":
      setResponseStatus(event, 404);
      return { status: "not-needed" };
    case "not-found":
      throw createError({ statusCode: 404, statusMessage: "Recipe not found" });
  }
});
